(() => {
  document.querySelectorAll('[data-integration]').forEach(button=>button.addEventListener('click',()=>{
    document.querySelectorAll('[data-integration]').forEach(icon=>icon.setAttribute('aria-pressed',String(icon===button)));
    document.querySelector('.orbit-detail-category').textContent=button.dataset.category.toUpperCase();
    document.querySelector('.orbit-detail-name').textContent=button.dataset.integration;
    document.querySelector('.orbit-detail-copy').textContent=button.dataset.detail;
  }));
  const inboxSection=document.getElementById("one-inbox");
  addEventListener("message",event=>{const frame=inboxSection.querySelector("iframe");if(event.source===frame.contentWindow&&event.data?.type==="whatsmine-inbox-height"&&Number.isFinite(event.data.height)){frame.style.height=Math.max(700,Math.min(2200,event.data.height))+"px";}});
  const media = matchMedia('(prefers-reduced-motion: reduce)');
  let paused = media.matches;
  const names = {inbox:'Unified Inbox',dashboard:'Dashboard',automation:'Automation Builder',templates:'Message Templates'};
  const stage = document.querySelector('.stage');
  stage.insertAdjacentHTML('afterbegin', `<div class="stage-wrap"><div class="product-frame"><div class="frame-bar"><b>◈ WhatsMine / Cedar Studio</b><span class="live-pill">PRODUCT PREVIEW</span></div><button class="screen-display" data-view="inbox" aria-label="Expand inbox preview" data-expand></button><div class="product-tabs" role="group" aria-label="Explore product screens">${Object.entries(names).map(([view,label])=>`<button data-product-tab="${view}" aria-pressed="${view==='inbox'}">${label}</button>`).join('')}</div></div><div class="scene-chip"><span class="spark">✧</span><div><b>Everything your team needs.</b><small>Conversations → Context → Next steps</small></div></div></div>`);
  const heroStage = stage.querySelector('.stage-wrap');
  heroStage.classList.add('mascot-stage');
  heroStage.insertAdjacentHTML('afterbegin', '<div class="bot-aura" aria-hidden="true"></div><img class="hero-bot" src="assets/whatsmine-bot.png" width="1024" height="1536" fetchpriority="high" alt="Friendly forest-green and ivory WhatsMine AI assistant mascot"><div class="bot-message"><span>✧</span><div><b>Your next great conversation?</b><small>Let’s make it happen together.</small></div></div>');
  heroStage.querySelector('.product-frame').hidden = true;
  heroStage.querySelector('.bot-message b').textContent = 'A little help. A better reply.';
  heroStage.querySelector('.bot-message small').textContent = 'Your AI teammate is here.';
  heroStage.querySelector('.scene-chip b').textContent = 'One connected workspace.';
  heroStage.querySelector('.scene-chip small').textContent = 'Conversations. Context. Action.';
  document.querySelector('.preview-label').textContent='Meet your AI teammate';
  document.querySelector('.hero-buttons .btn:first-child').innerHTML='Explore the workspace <span>↗</span>';
  document.querySelector('.hero-buttons .btn:first-child').removeAttribute('data-demo');
  document.querySelector('.hero-buttons .btn:first-child').href='#product-story';
  document.querySelector('.hero-buttons .btn.outline').href='#product-story';
  document.querySelector('.workflow').insertAdjacentHTML('afterbegin','<div class="workflow-preview"><div class="workflow-overlay"><i></i> ORDER CONFIRMATION / APPROVED TEMPLATE FLOW</div><button class="screen-display" data-view="automation" data-expand aria-label="Expand automation preview"></button></div>');
  document.querySelector('.mini-inbox').insertAdjacentHTML('beforebegin','<div class="feature-image"><button class="screen-display" data-view="inbox" data-expand aria-label="Expand inbox preview"></button></div>');
  const steps = [ ['dashboard','01 / UNDERSTAND','See your business clearly.','Review message activity, conversations and team workflows.'], ['inbox','02 / CONNECT','Bring every conversation together.','Keep customer details and the next reply in one shared inbox.'], ['automation','03 / ORCHESTRATE','Make the next step happen.','Connect order events, decisions and approved templates.'], ['templates','04 / COMMUNICATE','Make every message thoughtful.','Organize reusable messages and see approval status at a glance.'] ];
  const story = document.createElement('section');story.className='product-story';story.id='product-story';
  story.innerHTML=`<div class="story-pin"><div class="wrap story-layout"><div class="story-copy"><div class="eyebrow" style="color:#d6f279">ONE CONNECTED EXPERIENCE</div><h2>Your business.<br>In full flow.</h2><p>Scroll through the workspace, or choose a chapter to explore.</p>${steps.map(([view,number,title,description],i)=>`<button class="story-step ${i===0?'active':''}" data-story="${view}" aria-pressed="${i===0}"><small>${number}</small><h3>${title}</h3><p>${description}</p></button>`).join('')}</div><div><div class="story-product"><div class="story-caption"><b id="story-name">Dashboard</b><span>CEDAR STUDIO / DEMO WORKSPACE</span></div><button class="screen-display" data-view="dashboard" data-expand aria-label="Expand product story preview"></button><div class="story-meter"><i></i></div></div><div class="flow-ribbon"><b>Connect</b><svg viewBox="0 0 38 16" aria-hidden="true"><path d="M0 8 H38"/></svg><b>Understand</b><svg viewBox="0 0 38 16" aria-hidden="true"><path d="M0 8 H38"/></svg><b>Act</b></div></div></div></div>`;
  document.querySelector('.trust').after(story);
  document.body.insertAdjacentHTML('beforeend','<div class="scroll-progress" aria-hidden="true"></div><button class="motion-control" aria-pressed="false">Pause motion Ⅱ</button><dialog class="image-dialog"><div class="image-dialog-head"><span>WhatsMine / Product previews / Fictional demo data</span><button data-close-image>Close ×</button></div><img src="assets/product-ui-preview.png" alt="Dashboard, inbox, automation builder and message templates recreated with demo data"></dialog>');
  const lightbox=document.querySelector('.image-dialog');document.querySelectorAll('[data-expand]').forEach(button=>button.addEventListener('click',()=>lightbox.showModal()));document.querySelector('[data-close-image]').addEventListener('click',()=>lightbox.close());
  const screen=document.querySelector('.product-frame .screen-display');
  const transition=(el,view)=>{el.dataset.view=view;if(!paused&&el.animate)el.animate([{opacity:.45,transform:'translateY(7px)'},{opacity:1,transform:'translateY(0)'}],{duration:450,easing:'cubic-bezier(.2,.8,.2,1)'});};
  document.querySelectorAll('[data-product-tab]').forEach(button=>button.addEventListener('click',()=>{transition(screen,button.dataset.productTab);document.querySelectorAll('[data-product-tab]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));screen.setAttribute('aria-label','Expand '+names[button.dataset.productTab]+' preview');}));
  let pending=false;const update=()=>{pending=false;const total=document.documentElement.scrollHeight-innerHeight;document.querySelector('.scroll-progress').style.width=(total>0?scrollY/total*100:0)+'%';document.querySelector('.header').classList.toggle('scrolled',scrollY>35);};
  addEventListener('scroll',()=>{if(!pending){pending=true;requestAnimationFrame(update);}},{passive:true});addEventListener('resize',update);update();
  const frame=document.querySelector('.product-frame');stage.addEventListener('pointermove',event=>{if(paused||innerWidth<1000||event.pointerType==='touch')return;const rect=stage.getBoundingClientRect();const x=(event.clientX-rect.left)/rect.width-.5,y=(event.clientY-rect.top)/rect.height-.5;frame.style.transform=`perspective(1600px) rotateY(${x*7-3}deg) rotateX(${-y*5+2}deg)`;});stage.addEventListener('pointerleave',()=>frame.style.transform='');
  const motion=document.querySelector('.motion-control');motion.addEventListener('click',()=>{paused=!paused;document.body.classList.toggle('motion-paused',paused);motion.textContent=paused?'Resume motion ▷':'Pause motion Ⅱ';motion.setAttribute('aria-pressed',String(paused));frame.style.transform='';});media.addEventListener('change',()=>{paused=media.matches;document.body.classList.toggle('motion-paused',paused);motion.setAttribute('aria-pressed',String(paused));motion.textContent=paused?'Resume motion ▷':'Pause motion Ⅱ';frame.style.transform='';});
  document.querySelector('.prototype-note').firstChild.textContent='DESIGN PREVIEW · Explore screens & scroll story';
})();
